validator:
function validate(input) {
  const [{ Listens = [], Friendship = [] }] = input;
  const date = /^\d{4}-\d{2}-\d{2}$/;
  for (const [user, song, day] of Listens) {
    if (user === null || song === null) return 'Every listen needs a user_id and a song_id.';
    if (!date.test(String(day))) return `User ${user} has a listen with a malformed day.`;
  }
  const pairs = new Set();
  for (const [a, b] of Friendship) {
    if (a === null || b === null) return 'Every friendship needs both user ids.';
    if (!(a < b)) return `Friendship (${a}, ${b}) must have user1_id < user2_id.`;
    const key = `${a}|${b}`;
    if (pairs.has(key)) return `Friendship (${a}, ${b}) appears twice.`;
    pairs.add(key);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const users = small ? 5 : 120;
  const songs = small ? [10, 11, 12, 13] : Array.from({ length: 25 }, (_, i) => i + 1);
  const days = small ? ['2021-03-15', '2021-03-16'] : ['2021-03-14', '2021-03-15', '2021-03-16', '2021-03-17'];
  const cap = small ? 8 : 2000;
  const Listens = [], Friendship = [], pairs = new Set();
  const befriend = (a, b) => {
    if (a === b) return;
    const [x, y] = a < b ? [a, b] : [b, a];
    if (!pairs.has(`${x}|${y}`)) { pairs.add(`${x}|${y}`); Friendship.push([x, y]); }
  };
  // Plant pairs that share three songs on one day, often with one change that makes them a near miss.
  const plants = small ? (rand() < 0.7 ? 1 : 0) : 60;
  for (let p = 0; p < plants && Listens.length + 6 <= cap; p++) {
    const a = 1 + Math.floor(rand() * users);
    let b = 1 + Math.floor(rand() * users);
    if (b === a) b = a % users + 1;
    const day = pick(days);
    const set = [...songs].sort(() => rand() - 0.5).slice(0, 3);
    const twist = rand();
    set.forEach((song, i) => {
      Listens.push([a, song, day]);
      if (i === 2 && twist < 0.15) Listens.push([b, song, days.find(d => d !== day)]);
      else if (i === 2 && twist < 0.3) Listens.push([b, set[0], day]);
      else Listens.push([b, song, day]);
    });
    if (rand() < 0.8) befriend(a, b);
  }
  const rows = small ? Math.floor(rand() * (cap - Listens.length + 1)) + Listens.length : cap;
  while (Listens.length < rows) {
    if (Listens.length && rand() < 0.1) Listens.push([...pick(Listens)]);
    else Listens.push([1 + Math.floor(rand() * users), pick(songs), pick(days)]);
  }
  const extra = small ? Math.floor(rand() * 4) : 300;
  for (let i = 0; i < extra; i++) befriend(1 + Math.floor(rand() * users), 1 + Math.floor(rand() * users));
  // Shuffle so related rows are not adjacent.
  for (let i = Listens.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [Listens[i], Listens[j]] = [Listens[j], Listens[i]]; }
  return [{ Listens, Friendship }];
}
